import { parentSectorLabel } from '@sdk/sectors.sdk'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'
import{useMemo,useState}from'react';import{Link}from'react-router';import{FolderOpen,RotateCcw,ShieldAlert,Trash2}from'lucide-react';import{ComplaintWorkflow}from'../../components/ComplaintUi';import{useComplaintArchiveFolders,useComplaintDeletionRequests,useComplaintReportDownload,useComplaintReports,useRequestComplaintDeletion,useRestoreComplaintEmail}from'@features/complaints'
export default function ArchivePage(){const{data:folders=[],isLoading}=useComplaintArchiveFolders();const{data:requests=[]}=useComplaintDeletionRequests();const{data:reports=[]}=useComplaintReports();const restore=useRestoreComplaintEmail();const requestDelete=useRequestComplaintDeletion();const download=useComplaintReportDownload();const[search,setSearch]=useState('');const[reason,setReason]=useState<Record<string,string>>({});const[open,setOpen]=useState<string|null>(null);const shown=useMemo(()=>folders.filter(folder=>`${folder.subject} ${folder.senderEmail}`.toLowerCase().includes(search.toLowerCase())),[folders,search]);return <section className="min-h-full space-y-5 pb-8" dir="rtl"><ExecPageHeader icon="archive-box" title="أرشيف الشكاوى" subtitle="كل مجلد يمثل بريداً كاملاً مع تذاكره وصوره وتقاريره. النقل إلى هنا لا يحذف أي بيانات." /><ComplaintWorkflow current="archive"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="ابحث بموضوع البريد أو المرسل" className="w-full rounded-2xl border bg-white p-3"/>{isLoading?<p>جارٍ التحميل…</p>:!shown.length?<p className="rounded-3xl border border-dashed bg-white p-12 text-center text-slate-500">لا توجد مجلدات مؤرشفة.</p>:<div className="grid gap-4 md:grid-cols-2">{shown.map(folder=>{const deletion=requests.find(value=>value.folderId===folder.id&&['pending','approved','executing','failed'].includes(value.status));const folderReports=reports.filter(report=>report.inboxMessageId===folder.inboxMessageId);return <article key={folder.id} className="rounded-3xl border bg-white p-5 shadow-sm"><button onClick={()=>setOpen(open===folder.id?null:folder.id)} className="flex w-full items-start gap-3 text-right"><FolderOpen className="text-amber-500" size={32}/><div className="flex-1"><h2 className="font-black">{folder.subject}</h2><p dir="ltr" className="break-all text-right text-xs text-slate-500">{folder.senderEmail}</p><p className="mt-2 text-xs text-slate-500">{new Date(folder.archivedAt).toLocaleString('ar-IQ-u-nu-latn')} · {parentSectorLabel(folder.sector)}</p></div></button>{open===folder.id&&<div className="mt-4 space-y-3 border-t pt-4"><p className="text-sm">المرفقات عند الأرشفة: <b>{String(folder.snapshot.attachmentCount??0)}</b></p>{folderReports.map(report=><div key={report.id} className="flex min-w-0 items-center justify-between gap-3 rounded-xl bg-slate-50 p-3 text-sm"><Link to={`/complaints/reports/${report.id}`} className="min-w-0 break-words font-bold text-blue-700">{report.title}</Link>{report.pptxPath&&<button disabled={download.isPending} className="shrink-0 rounded-lg border bg-white px-3 py-2 font-bold text-slate-700" onClick={()=>download.mutate(report.pptxPath!,{onSuccess:url=>window.open(url,'_blank')})}>تنزيل</button>}</div>)}<button disabled={restore.isPending} onClick={()=>restore.mutate(folder.id)} className="flex w-full items-center justify-center gap-2 rounded-xl border p-3 font-bold text-blue-700"><RotateCcw size={17}/>استعادة البريد للعمل</button>{deletion?<p className="rounded-xl bg-amber-50 p-3 text-sm font-bold text-amber-800"><ShieldAlert className="ml-2 inline"/>طلب الحذف النهائي: {deletion.status==='pending'?'بانتظار مدير النظام':deletion.status==='approved'?'تمت الموافقة وينتظر التنفيذ الآمن':deletion.status==='executing'?'جارٍ حذف الملفات بأمان':'فشل التنفيذ وأُحيل إلى مدير النظام لإعادة المحاولة'}</p>:<div className="rounded-xl border border-rose-200 bg-rose-50 p-3"><label className="text-xs font-bold">سبب طلب الحذف النهائي<input value={reason[folder.id]??''} onChange={e=>setReason(old=>({...old,[folder.id]:e.target.value}))} className="mt-1 w-full rounded-lg border bg-white p-2"/></label><button disabled={(reason[folder.id]??'').trim().length<5} onClick={()=>requestDelete.mutate({folderId:folder.id,reason:reason[folder.id]??''})} className="mt-2 flex w-full items-center justify-center gap-2 rounded-xl bg-rose-700 p-3 font-bold text-white disabled:opacity-40"><Trash2 size={17}/>إرسال طلب حذف نهائي لمدير النظام</button></div>}</div>}</article>})}</div>}</section>}
